import { TaskStatus, isClosedStatus, type Cycle, type WorkTask } from "../../types/work-projects"
import type { LeaveRequest } from "../../types/work-planning"
import type { Employee } from "../../types/workforce"
import { addDays } from "./billing"
import { datesBetween, employeeWorkDays, halfLeaveDays, hoursPerDay, leaveDays, rangesOverlap } from "./planning"
import { daysBetween } from "./project-metrics"

/**
 * Cycles (sprints) of a project (P4): their state, the burn-down of the work
 * committed, each person's capacity in the cycle and what moves on when a
 * cycle closes.
 */

export const MIN_CYCLE_DAYS = 1
export const MAX_CYCLE_DAYS = 28
export const MAX_CYCLE_NAME = 60

export type CycleState = "upcoming" | "active" | "ended" | "closed"

/** Upcoming before it starts, active while it runs, ended once past its last day until someone closes it. */
export function cycleState(c: Pick<Cycle, "startDate" | "endDate" | "closedAt">, today: string): CycleState {
  if (c.closedAt) return "closed"
  if (today < c.startDate) return "upcoming"
  if (today > c.endDate) return "ended"
  return "active"
}

export const cycleLength = (c: Pick<Cycle, "startDate" | "endDate">) => daysBetween(c.startDate, c.endDate) + 1

/** Dates in order, 1 to 28 days long, and never overlapping another cycle of the project. */
export function assertCycle(c: Pick<Cycle, "name" | "startDate" | "endDate">, others: Pick<Cycle, "id" | "startDate" | "endDate">[], id?: string) {
  if (!c.name.trim()) throw new Error("Give the cycle a name")
  if (c.name.trim().length > MAX_CYCLE_NAME) throw new Error("A cycle name can have up to 60 characters")
  const iso = /^\d{4}-\d{2}-\d{2}$/
  if (!iso.test(c.startDate) || !iso.test(c.endDate) || c.endDate < c.startDate) throw new Error("The cycle ends before it starts")
  const days = cycleLength(c)
  if (days < MIN_CYCLE_DAYS || days > MAX_CYCLE_DAYS) throw new Error("A cycle lasts between 1 day and 4 weeks")
  if (others.some((o) => o.id !== id && rangesOverlap(c.startDate, c.endDate, o.startDate, o.endDate))) throw new Error("Cycles of a project can't overlap")
}

/** Where the next cycle goes: the day after the last one, as long as the last one (two weeks by default). */
export function nextCycleDates(cycles: Pick<Cycle, "startDate" | "endDate">[], today: string, lengthDays = 14) {
  const last = [...cycles].sort((a, b) => b.endDate.localeCompare(a.endDate))[0]
  const start = last && addDays(last.endDate, 1) > today ? addDays(last.endDate, 1) : today
  const length = last ? Math.min(MAX_CYCLE_DAYS, cycleLength(last)) : lengthDays
  return { startDate: start, endDate: addDays(start, length - 1) }
}

/** The tasks a cycle holds; cancelled ones don't count. */
export const cycleTasks = (tasks: WorkTask[], cycleId: string) => tasks.filter((t) => t.cycleId === cycleId && t.status !== TaskStatus.CANCELLED)

/** Done on or before a day (a task done with no date counts as done from the start). */
const doneBy = (t: Pick<WorkTask, "status" | "completedAt">, day: string) => t.status === TaskStatus.DONE && (!t.completedAt || t.completedAt.slice(0, 10) <= day)

export interface CycleProgress {
  committedHours: number
  doneHours: number
  totalTasks: number
  doneTasks: number
  /** 0–100, by hours (each task weighs at least one hour) */
  percent: number
}

const weight = (t: Pick<WorkTask, "estimatedHours">) => Math.max(1, t.estimatedHours)

export function cycleProgress(tasks: WorkTask[]): CycleProgress {
  const committed = tasks.reduce((s, t) => s + weight(t), 0)
  const done = tasks.filter((t) => t.status === TaskStatus.DONE)
  const doneHours = done.reduce((s, t) => s + weight(t), 0)
  return {
    committedHours: Math.round(committed * 10) / 10,
    doneHours: Math.round(doneHours * 10) / 10,
    totalTasks: tasks.length,
    doneTasks: done.length,
    percent: committed ? Math.round((doneHours / committed) * 100) : 0,
  }
}

export interface BurndownPoint {
  date: string
  /** Hours left if the work went down evenly */
  ideal: number
  /** Hours actually left at the end of the day; null for days still to come */
  remaining: number | null
}

/**
 * One point per day of the cycle: the ideal straight line from the hours
 * committed down to zero, and the hours really left (tasks not yet done that
 * day), until today.
 */
export function burndown(cycle: Pick<Cycle, "startDate" | "endDate">, tasks: WorkTask[], today: string): BurndownPoint[] {
  const days = datesBetween(cycle.startDate, cycle.endDate)
  const committed = tasks.reduce((s, t) => s + weight(t), 0)
  const steps = Math.max(1, days.length - 1)
  return days.map((date, i) => ({
    date,
    ideal: Math.round((committed - (committed * i) / steps) * 10) / 10,
    remaining: date > today ? null : Math.round(tasks.filter((t) => !doneBy(t, date)).reduce((s, t) => s + weight(t), 0) * 10) / 10,
  }))
}

export interface MemberCapacity {
  employeeId: string
  /** Days they work in the cycle, after holidays and leave (half days count half) */
  days: number
  leaveDays: number
  capacityHours: number
  /** Estimated hours of the cycle's open tasks they lead */
  committedHours: number
  /** committed ÷ capacity, in % */
  load: number
}

/**
 * How much each team member can take on in a cycle: their working days
 * (holidays removed) minus approved leave, times their hours per day,
 * against the open work of the cycle assigned to them.
 */
export function cycleCapacity(
  cycle: Pick<Cycle, "startDate" | "endDate">,
  team: Employee[],
  tasks: WorkTask[],
  leave: LeaveRequest[],
  holidays: Iterable<string> = []
): MemberCapacity[] {
  const off = [...holidays]
  return team.map((e) => {
    const work = employeeWorkDays(e, cycle.startDate, cycle.endDate, off)
    const away = leaveDays(leave, e.id, cycle.startDate, cycle.endDate)
    const half = halfLeaveDays(leave, e.id, cycle.startDate, cycle.endDate)
    const days = work.reduce((n, d) => n + (away.has(d) ? 0 : half.has(d) ? 0.5 : 1), 0)
    const leaveCount = work.reduce((n, d) => n + (away.has(d) ? 1 : half.has(d) ? 0.5 : 0), 0)
    const capacityHours = Math.round(hoursPerDay(e) * days * 10) / 10
    const committedHours = Math.round(tasks.filter((t) => t.assigneeId === e.id && !isClosedStatus(t.status)).reduce((s, t) => s + t.estimatedHours, 0) * 10) / 10
    return { employeeId: e.id, days, leaveDays: leaveCount, capacityHours, committedHours, load: capacityHours > 0 ? Math.round((committedHours / capacityHours) * 100) : committedHours > 0 ? 999 : 0 }
  })
}

/** The open cycle that comes right after this one, if any. */
export function followingCycle<T extends Pick<Cycle, "id" | "startDate" | "closedAt">>(cycles: T[], cycle: Pick<Cycle, "id" | "startDate">) {
  return cycles.filter((c) => c.id !== cycle.id && !c.closedAt && c.startDate > cycle.startDate).sort((a, b) => a.startDate.localeCompare(b.startDate))[0]
}
